template <typename T>
class Vector {
private:
    T* data_;
    size_t size_;
    size_t capacity_;
public:
    Vector() : data_(nullptr), size_(0), capacity_(0) {}
    void push_back(const T& val) {
        if (size_ == capacity_) reserve(capacity_ == 0 ? 1 : capacity_ * 2);
        data_[size_++] = val;
    }
};

