type Result<T, E = Error> = { ok: true; value: T } | { ok: false; error: E };

export const safeParse = (input: string): Result<object> => {
    try {
        return { ok: true, value: JSON.parse(input) };
    } catch (err) {
        return { ok: false, error: err as Error };
    }
};

